    [Xunit.Fact]
    public static void TestCellsGrowAppendsCopies() {
        emon.Port.Cells c = emon.Port.NewCells();
        emon.Port.CellsPush(c, 9);
        emon.Port.CellsGrow(c, 40, 7);
        emon.Testport.AssertEq(emon.Port.CellsLen(c), 41, "length");
        emon.Testport.AssertEq(emon.Port.CellsAt(c, 0), 9, "the old cell");
        emon.Testport.AssertEq(emon.Port.CellsAt(c, 1), 7, "first new");
        emon.Testport.AssertEq(emon.Port.CellsAt(c, 40), 7, "last new");
        emon.Port.CellsGrow(c, 0, 1);
        emon.Testport.AssertEq(emon.Port.CellsLen(c), 41, "growing by zero changes nothing");
    }
